/**
 * Check if a date string is in YYYY-MM-DD format and is a real date.
 * @param {string} dateStr
 * @returns {boolean}
 */
export function isValidDate(dateStr) {
  if (typeof dateStr !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return false;
  const [year, month, day] = dateStr.split('-');
  const y = Number(year);
  const m = Number(month);
  const d = Number(day);

  const date = new Date(dateStr + 'T00:00:00Z');
  return (
    !isNaN(date.getTime()) &&
    date.getUTCFullYear() === y &&
    date.getUTCMonth() + 1 === m &&
    date.getUTCDate() === d
  );
}

/**
 * Add days to a date string (in UTC).
 * @param {string} dateStr - YYYY-MM-DD format
 * @param {number} days - Number of days to add
 * @returns {string} - YYYY-MM-DD format
 */
export function addDays(dateStr, days) {
  const date = new Date(dateStr + 'T00:00:00Z');
  date.setUTCDate(date.getUTCDate() + days);

  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, '0');
  const day = String(date.getUTCDate()).padStart(2, '0');

  return `${year}-${month}-${day}`;
}

/**
 * Calculate the number of whole days between two dates (b minus a, in UTC).
 * @param {string} a - YYYY-MM-DD format
 * @param {string} b - YYYY-MM-DD format
 * @returns {number} - Whole days (b - a)
 */
export function daysBetween(a, b) {
  const dateA = new Date(a + 'T00:00:00Z');
  const dateB = new Date(b + 'T00:00:00Z');

  const msPerDay = 86400000;
  const diffMs = dateB.getTime() - dateA.getTime();

  return Math.floor(diffMs / msPerDay);
}

